bool sigset_isequal(FAR const sigset_t *left, FAR const sigset_t *right)
{
  int ndx;

  /* Check if all elements of the set are the same */

  for (ndx = 0; ndx < _SIGSET_NELEM; ndx++)
    {
      if (right->_elem[ndx] != left->_elem[ndx])
        {
          return false;
        }
    }

  return true;
}

