{
  struct sigaction act;
  int ret;

  /* Ignore the signal */

  act.sa_handler = SIG_IGN;
  act.sa_flags   = 0;

  ret = sigemptyset(&act.sa_mask);
  if (ret == OK)
    {
      ret = sigaction(signo, &act, NULL);
    }

  return ret;
}

